// === Validation & normalisation ===
// Entrée: lignes brutes du Sheet prospects_in
// Sortie: 1 item par prospect valide, normalisé

const REQUIRED = ['company_name', 'email', 'city', 'niche'];
const now = new Date().toISOString();

const out = [];
let idx = 0;

for (const item of items) {
  const r = item.json || {};
  idx += 1;

  // ID auto si manquant
  const id = (r.id && String(r.id).trim()) || `p_${Date.now()}_${idx.toString().padStart(4, '0')}`;

  // Validation des champs obligatoires
  const missing = REQUIRED.filter(k => !r[k] || String(r[k]).trim() === '');

  // Validation email simple
  const email = String(r.email || '').trim().toLowerCase();
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  // opt_out (string "true"/"false" ou bool)
  const optOut = r.opt_out === true || String(r.opt_out || '').toLowerCase() === 'true';

  const errors = [];
  if (missing.length) errors.push(`missing:${missing.join(',')}`);
  if (!emailOk) errors.push('invalid_email');
  if (optOut) errors.push('opt_out');

  const prospect = {
    id,
    company_name: String(r.company_name || '').trim(),
    contact_name: String(r.contact_name || '').trim(),
    email,
    website_url: String(r.website_url || '').trim(),
    city: String(r.city || '').trim(),
    niche: String(r.niche || '').trim().toLowerCase(),
    notes: String(r.notes || '').trim(),
    source_url: String(r.source_url || '').trim(),
    opt_out: optOut,
    status: errors.length ? 'error' : 'pending',
    created_at: now,
    updated_at: now,
    errors
  };

  out.push({ json: prospect });
}

return out;

