// Parse réponse LLM A1 et merge dans le prospect
const out = [];
for (const item of items) {
  const prev = item.json.prospect_in || item.json; // tolère les deux formes
  // En SplitInBatches le prospect courant est dans $json à la racine d'origine,
  // mais ici on reçoit le résultat du HTTP Request. Le prospect est passé par n8n via $('Boucle Prospect (1 par 1)').
  // On reconstruit en lisant l'item input via $items.
  const llmRaw = item.json;
  let parsed = {};
  try {
    const content = llmRaw && llmRaw.choices && llmRaw.choices[0] && llmRaw.choices[0].message && llmRaw.choices[0].message.content;
    if (!content) throw new Error('LLM_NO_CONTENT');
    parsed = JSON.parse(content);
  } catch (e) {
    parsed = { _llm_error: String(e && e.message || e) };
  }
  // récupère prospect courant depuis le node SplitInBatches
  const prospect = $('Boucle Prospect (1 par 1)').first().json;
  out.push({
    json: {
      ...prospect,
      analysis: parsed,
      status: parsed._llm_error ? 'error' : 'analyzed',
      updated_at: new Date().toISOString()
    }
  });
}
return out;

