// Construit la ligne finale prête pour review_queue
const out = [];
for (const item of items) {
  const p = item.json;
  const a = p.analysis || {};
  const s = p.score || {};
  const e = p.email || {};

  // Règle d'attribution simple :
  // - Difficulté simple/medium → Arsène (commercial + delivery)
  // - Difficulté complex → Arsène + Kentin
